import fs from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { TraceMap, originalPositionFor } from "@jridgewell/trace-mapping";
import { createPageReports, saveReplay, healthPayload, renderClientSource, rrwebAsset, resolveRrwebMode, resolveFabMode, resolveNetworkMode, } from "./core.js";
const ASSET_DIR = path.dirname(fileURLToPath(import.meta.url));
// Fail open: an overlay bug must degrade to "no overlay", never to "no app". Logged once per site.
const warned = new Set();
function warnOnce(site, e) {
    if (warned.has(site))
        return;
    warned.add(site);
    console.warn(`[emergent-overlay] ${site} failed; overlay degraded for this server:`, e instanceof Error ? e.message : e);
}
// ±2-line excerpt of the original source with a > marker and column caret.
function codeFrame(src, line, column) {
    const lines = src.split("\n");
    const start = Math.max(0, line - 3);
    const end = Math.min(lines.length, line + 2);
    const width = String(end).length;
    const out = [];
    for (let i = start; i < end; i++) {
        const no = String(i + 1).padStart(width);
        out.push(`${i + 1 === line ? ">" : " "} ${no} | ${lines[i]}`);
        if (i + 1 === line)
            out.push(`  ${" ".repeat(width)} | ${" ".repeat(Math.max(0, column))}^`);
    }
    return out.join("\n");
}
// Injects a classic (non-module) script that renders Emergent-branded overlays for both
// build errors (via its own vite-hmr socket; the built-in overlay is disabled in
// vite.config.ts) and runtime errors — so a crash never leaves a blank page.
export function emergentOverlay() {
    let root = process.cwd();
    let base = "/";
    let hmrEnabled = true;
    const rrwebMode = resolveRrwebMode();
    const fabMode = resolveFabMode();
    const networkMode = resolveNetworkMode();
    return {
        name: "emergent-overlay",
        apply: "serve",
        configResolved(config) {
            try {
                root = config.root;
                base = config.base || "/";
                hmrEnabled = config.server.hmr !== false;
            }
            catch (e) {
                warnOnce("configResolved", e);
            }
        },
        configureServer(server) {
            try {
                // Vite 8 dropped error buffering: a socket that connects after a build error never
                // hears about it. Cache errors server-side, keyed per module so a successful HMR
                // update of an unrelated file can't clear another module's outstanding error.
                const buildErrors = new Map();
                for (const env of Object.values(server.environments)) {
                    const orig = env.hot.send.bind(env.hot);
                    env.hot.send = ((...args) => {
                        try {
                            const p = args[0];
                            if (p && typeof p === "object" && p.type) {
                                if (p.type === "error")
                                    buildErrors.set(String(p.err?.id || "unknown").split("?")[0], p.err);
                                else if (p.type === "full-reload")
                                    buildErrors.clear(); // reload re-triggers anything still broken
                                else if (p.type === "prune") {
                                    // de-imported modules can never re-transform, so their errors would be permanent
                                    const pruned = (p.paths || []).map((v) => String(v).split("?")[0]);
                                    for (const key of [...buildErrors.keys()]) {
                                        if (pruned.some((pth) => key === pth || (pth.startsWith("/") && key.endsWith(pth))))
                                            buildErrors.delete(key);
                                    }
                                }
                                else if (p.type === "update") {
                                    const paths = (p.updates || [])
                                        .flatMap((u) => [u.path, u.acceptedPath])
                                        .filter((v) => !!v)
                                        .map((v) => v.split("?")[0]);
                                    for (const key of [...buildErrors.keys()]) {
                                        // exact-boundary match only: /src/foo.ts must not clear /src/foo.tsx, and
                                        // unidentified ("unknown") errors are kept until a full reload revalidates
                                        if (paths.some((pth) => key === pth || (pth.startsWith("/") && key.endsWith(pth))))
                                            buildErrors.delete(key);
                                    }
                                }
                            }
                        }
                        catch (e) {
                            warnOnce("hmr bookkeeping", e); // never stand between Vite and its client
                        }
                        orig(...args);
                    });
                }
                // Routes are mounted at the resolved base: plugin middleware runs before Vite's
                // base-stripping, so with base "/preview/" the request path keeps the prefix.
                const route = (pth) => (base === "/" ? pth : base.replace(/\/$/, "") + pth);
                // Overlay pages report error + splash state over Vite's token-authenticated hot
                // channel (Replit-shape: no open HTTP write endpoint).
                const pageReports = createPageReports();
                const clientHot = server.environments.client.hot;
                clientHot.on("emergent-overlay:report", (data) => {
                    try {
                        pageReports.record(data);
                    }
                    catch (e) {
                        warnOnce("report", e);
                    }
                });
                // Rewrites a browser runtime stack (transformed-module coordinates) to original
                // source positions using the sourcemaps already in Vite's module graph, and builds
                // a code frame for the first app frame. Best-effort: unresolvable lines pass through.
                const FRAME_RE = /((?:https?:\/\/[^\s()]+?|\/[^\s():]+?)):(\d+):(\d+)/;
                async function resolveStack(rawStack) {
                    const graph = server.environments.client.moduleGraph;
                    let anchorFile = null;
                    let frame = null;
                    const outLines = [];
                    for (const lineText of String(rawStack).split("\n").slice(0, 30)) {
                        const m = lineText.match(FRAME_RE);
                        if (!m) {
                            outLines.push(lineText);
                            continue;
                        }
                        let pathname = m[1];
                        try {
                            if (pathname.startsWith("http"))
                                pathname = new URL(pathname).pathname;
                        }
                        catch {
                            /* not a URL — treat as a path */
                        }
                        pathname = pathname.split("?")[0];
                        if (base !== "/" && pathname.startsWith(base))
                            pathname = "/" + pathname.slice(base.length);
                        let mod;
                        try {
                            mod = await graph.getModuleByUrl(pathname);
                        }
                        catch {
                            mod = undefined;
                        }
                        const map = mod?.transformResult?.map;
                        if (!mod || !map) {
                            outLines.push(lineText);
                            continue;
                        }
                        let pos;
                        try {
                            pos = originalPositionFor(new TraceMap(map), { line: Number(m[2]), column: Number(m[3]) - 1 });
                        }
                        catch {
                            pos = null;
                        }
                        if (!pos || pos.line == null) {
                            outLines.push(lineText);
                            continue;
                        }
                        // label + content come from the source the position actually maps to — transform
                        // maps can carry multiple sources, and sources[0] is not necessarily the right one
                        const srcIdx = pos.source && map.sources
                            ? map.sources.indexOf(pos.source)
                            : -1;
                        const sourceFile = pos.source && path.isAbsolute(pos.source) ? pos.source : (mod.file ?? pathname);
                        const rel = path.relative(root, sourceFile).replace(/\\/g, "/");
                        const loc = `${rel}:${pos.line}:${(pos.column ?? 0) + 1}`;
                        outLines.push(lineText.replace(m[0], loc));
                        if (!anchorFile && !rel.includes("node_modules")) {
                            anchorFile = loc;
                            let src = (srcIdx >= 0 ? map.sourcesContent?.[srcIdx] : map.sourcesContent?.[0]) ?? null;
                            if (!src && path.isAbsolute(sourceFile) && sourceFile.startsWith(root) && fs.existsSync(sourceFile))
                                src = fs.readFileSync(sourceFile, "utf8");
                            if (src)
                                frame = codeFrame(src, pos.line, pos.column ?? 0);
                        }
                    }
                    return { stack: outLines.join("\n"), file: anchorFile, frame };
                }
                // Sourcemap resolution: request/reply over the hot channel with correlation ids.
                clientHot.on("emergent-overlay:resolve", (data, client) => {
                    const req = (data ?? {});
                    const id = typeof req.id === "string" ? req.id : "";
                    Promise.resolve()
                        .then(() => resolveStack(String(req.stack ?? "").slice(0, 20_000)))
                        .then((out) => client.send("emergent-overlay:resolved", { id, ...out }))
                        .catch(() => client.send("emergent-overlay:resolved", { id, stack: null, file: null, frame: null }));
                });
                // Vendored rrweb for buffer mode (served from the package, not the edge). Not named
                // rrweb.js on purpose: EasyPrivacy (uBlock/AdGuard/Brave default) blocks any URL containing /rrweb.js.
                server.middlewares.use(route("/__emergent_overlay__/recorder.js"), (_req, res) => {
                    try {
                        const asset = rrwebAsset(ASSET_DIR);
                        res.setHeader("Content-Type", "application/javascript; charset=utf-8");
                        res.setHeader("Cache-Control", "public, max-age=3600");
                        res.end(asset);
                    }
                    catch (e) {
                        warnOnce("recorder asset", e);
                        res.statusCode = 404;
                        res.end();
                    }
                });
                // Black-box dumps: ring-buffer replay + context, written to the workspace where
                // the agent (and the backup) can reach it. Capped per kind, oldest pruned.
                clientHot.on("emergent-overlay:crash-replay", (data, client) => {
                    try {
                        const req = (data ?? {});
                        const id = typeof req.id === "string" ? req.id : "";
                        const file = saveReplay(root, req);
                        client.send("emergent-overlay:crash-replay-saved", { id, file: path.relative(path.resolve(root, ".."), file) });
                    }
                    catch {
                        const req = (data ?? {});
                        client.send("emergent-overlay:crash-replay-saved", { id: typeof req.id === "string" ? req.id : "", file: null });
                    }
                });
                // Probe API: 200 = no build error and no freshly-reported client errors, else 503.
                server.middlewares.use(route("/__emergent_overlay__/health"), (req, res) => {
                    try {
                        // Deleted files can never emit the update that would clear their cached error.
                        for (const key of [...buildErrors.keys()]) {
                            if (path.isAbsolute(key) && !fs.existsSync(key))
                                buildErrors.delete(key);
                        }
                        const { status, body } = healthPayload(root, pageReports, [...buildErrors.values()]);
                        // The client's own fetches ask for ?client=1: same body, never a failed request in a browser.
                        res.statusCode = /[?&]client=1(?:&|$)/.test(req.url || "") ? 200 : status;
                        res.setHeader("Content-Type", "application/json");
                        res.end(body);
                    }
                    catch (e) {
                        // A broken probe must not read as a broken app.
                        warnOnce("health", e);
                        res.statusCode = 200;
                        res.setHeader("Content-Type", "application/json");
                        res.end(JSON.stringify({ healthy: true, degraded: "overlay-error" }));
                    }
                });
            }
            catch (e) {
                warnOnce("configureServer", e);
            }
        },
        transformIndexHtml() {
            let src;
            try {
                src = renderClientSource(ASSET_DIR, {
                    base,
                    hmrEnabled,
                    root,
                    rrwebMode,
                    fabMode,
                    networkMode,
                    transport: "hot",
                    token: "",
                });
            }
            catch (e) {
                warnOnce("inject", e); // serve the page untouched
                return [];
            }
            const tags = [
                {
                    tag: "script",
                    attrs: { "data-emergent-overlay": "" },
                    children: src,
                    injectTo: "head",
                },
            ];
            if (rrwebMode === "edge") {
                // Same marker + guard as the edge injector, so both layers can coexist:
                // the recorder itself no-ops when __emergentRrwebActive is already set.
                tags.push({ tag: "script", attrs: { defer: "", src: "/_emergent/rrweb/rrweb.min.js", "data-emergent-rrweb": "1" }, injectTo: "head" }, { tag: "script", attrs: { defer: "", src: "/_emergent/rrweb/recorder.js" }, injectTo: "head" });
            }
            // No hot channel (hmr: false) means nothing can ever flush the buffer: skip the
            // recorder entirely, which also keeps the bug button off (it only renders once recording).
            if (rrwebMode === "buffer" && hmrEnabled) {
                tags.push({
                    tag: "script",
                    attrs: { defer: "", src: (base === "/" ? "" : base.replace(/\/$/, "")) + "/__emergent_overlay__/recorder.js", "data-emergent-rrweb": "1" },
                    injectTo: "head",
                });
            }
            return tags;
        },
    };
}
